[CmdletBinding()]param([Parameter(Mandatory)][string]$SchemaPath,[Parameter(Mandatory)][string]$InstancePath,[switch]$NoExitFailure)
$ErrorActionPreference='Continue';$command=Get-Command node -ErrorAction SilentlyContinue;$node=if($command){$command.Source}else{$null};if(-not$node){$candidates=@($(if($env:MDF_NODE_PATH){$env:MDF_NODE_PATH}),$(if($env:USERPROFILE){Join-Path $env:USERPROFILE '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node.exe'}),$(if($env:LOCALAPPDATA){Join-Path $env:LOCALAPPDATA 'codex-runtimes/codex-primary-runtime/dependencies/node/bin/node.exe'}),$(if($env:ProgramFiles){Join-Path $env:ProgramFiles 'nodejs/node.exe'}));$node=@($candidates|Where-Object{$_-and(Test-Path $_)})|Select-Object -First 1};if(-not$node){throw 'Node.js is required for draft-2020-12 JSON Schema instance validation; set MDF_NODE_PATH when it is not on PATH.'};$json=& $node (Join-Path $PSScriptRoot 'test-json-schema-instance.js') $SchemaPath $InstancePath;$code=$LASTEXITCODE;$json;if($code-and-not$NoExitFailure){exit $code}
